[patterns/application/extensions/PTN-APP-EXT-017-extension-design-system-integration-pattern.md#example-3-using-design-system-components]

#### Example 3: Using Design System Components

_[To be completed]_

```typescript
// Extension component using design system components
import React from 'react';
import {
  Button,
  Input,
  Card,
  Alert,
  DataGrid
} from '@gainwell/design-system-react';

export const ClaimsValidatorContent: React.FC = () => {
  return (
    <Card title="Claims Validation">
      <Input
        label="Claim ID"
        placeholder="Enter claim ID"
        required
      />
      <Button
        variant="primary"
        onClick={handleValidate}
      >
        Validate Claim
      </Button>
      <Alert type="success">
        Validation passed
      </Alert>
      <DataGrid
        columns={columns}
        data={validationResults}
      />
    </Card>
  );
};
```

