[patterns/application/extensions/PTN-APP-EXT-017-extension-design-system-integration-pattern.md#example-5-composition-pattern-for-custom-components]

#### Example 5: Composition Pattern for Custom Components

_[To be completed]_

```typescript
// Composing design system components for custom UI
import { Card, Button, Badge } from '@gainwell/design-system-react';

export const ClaimStatusCard: React.FC<ClaimStatusProps> = ({ claim }) => {
  return (
    <Card>
      <Card.Header>
        <Card.Title>Claim {claim.id}</Card.Title>
        <Badge variant={claim.status}>{claim.statusLabel}</Badge>
      </Card.Header>
      <Card.Body>
        {claim.details}
      </Card.Body>
      <Card.Footer>
        <Button variant="secondary" size="small">
          View Details
        </Button>
        <Button variant="primary" size="small">
          Process Claim
        </Button>
      </Card.Footer>
    </Card>
  );
};
```
